/// <summary>
/// Why a call produced no value. A cancel is its own variant, so a
/// binding can turn it into its language's cancellation.
/// </summary>
internal class CoreException: UniffiException {
    CoreException() : base() {}
    CoreException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    public class Cancelled : CoreException {
        public Cancelled() : base() {}
    }
    
    
    
    public class Failed : CoreException {
        // Members
        public BoxedErrorInfo @info;

        // Constructor
        public Failed(
                BoxedErrorInfo @info) : base(
                "@info" + "=" + @info) {

            this.@info = @info;
        }
    }
    

    
}

class FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException>, CallStatusErrorHandler<CoreException> {
    public static FfiConverterTypeCoreError INSTANCE = new FfiConverterTypeCoreError();

    public override CoreException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CoreException.Cancelled();
            case 2:
                return new CoreException.Failed(
                    FfiConverterTypeBoxedErrorInfo.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Read()", value));
        }
    }

    public override int AllocationSize(CoreException value) {
        switch (value) {

            case CoreException.Cancelled variant_value:
                return 4;

            case CoreException.Failed variant_value:
                return 4
                    + FfiConverterTypeBoxedErrorInfo.INSTANCE.AllocationSize(variant_value.@info);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.AllocationSize()", value));
        }
    }

    public override void Write(CoreException value, BigEndianStream stream) {
        switch (value) {
            case CoreException.Cancelled variant_value:
                stream.WriteInt(1);
                break;
            case CoreException.Failed variant_value:
                stream.WriteInt(2);
                FfiConverterTypeBoxedErrorInfo.INSTANCE.Write(variant_value.@info, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Write()", value));
        }
    }
}





