/// <summary>
/// One thing that happened in a run, in the order it happened. Rows that
/// arrive between two drains come as one `RowsAppended` with the set's
/// row count at the last append.
/// </summary>
internal record RunEvent {
    
    public record ResultSetStarted (
        uint SetIndex,
        ResultColumnInfo[] Columns
    ) : RunEvent {}
    
    /// <summary>
    /// The columns of a set whose types the driver knew only once rows
    /// arrived.
    /// </summary>
    public record ColumnsResolved (
        uint SetIndex,
        ResultColumnInfo[] Columns
    ) : RunEvent {}
    
    public record RowsAppended (
        uint SetIndex,
        ulong RowCount
    ) : RunEvent {}
    
    public record RowLimitReached (
        uint SetIndex,
        ulong Retained
    ) : RunEvent {}
    
    public record ResultSetFinished (
        uint SetIndex,
        ulong RowCount,
        ulong? TotalRows,
        TruncationTag Truncation
    ) : RunEvent {}
    
    public record CommandCompleted (
        ulong? RowsAffected
    ) : RunEvent {}
    
    /// <summary>
    /// Something the server said that is not an error.
    /// </summary>
    public record Notice (
        string Severity,
        string Message,
        string? Code
    ) : RunEvent {}
    
    /// <summary>
    /// The last event of every run, with the transaction the editor's
    /// connection is left in.
    /// </summary>
    public record Finished (
        RunOutcome Outcome,
        TransactionStateTag Transaction
    ) : RunEvent {}
    

    
}

class FfiConverterTypeRunEvent : FfiConverterRustBuffer<RunEvent>{
    public static FfiConverterRustBuffer<RunEvent> INSTANCE = new FfiConverterTypeRunEvent();

    public override RunEvent Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new RunEvent.ResultSetStarted(
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterSequenceTypeResultColumnInfo.INSTANCE.Read(stream)
                );
            case 2:
                return new RunEvent.ColumnsResolved(
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterSequenceTypeResultColumnInfo.INSTANCE.Read(stream)
                );
            case 3:
                return new RunEvent.RowsAppended(
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 4:
                return new RunEvent.RowLimitReached(
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 5:
                return new RunEvent.ResultSetFinished(
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterOptionalUInt64.INSTANCE.Read(stream),
                    FfiConverterTypeTruncationTag.INSTANCE.Read(stream)
                );
            case 6:
                return new RunEvent.CommandCompleted(
                    FfiConverterOptionalUInt64.INSTANCE.Read(stream)
                );
            case 7:
                return new RunEvent.Notice(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterOptionalString.INSTANCE.Read(stream)
                );
            case 8:
                return new RunEvent.Finished(
                    FfiConverterTypeRunOutcome.INSTANCE.Read(stream),
                    FfiConverterTypeTransactionStateTag.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRunEvent.Read()", value));
        }
    }

    public override int AllocationSize(RunEvent value) {
        switch (value) {
            case RunEvent.ResultSetStarted variant_value:
                return 4
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.SetIndex)
                    + FfiConverterSequenceTypeResultColumnInfo.INSTANCE.AllocationSize(variant_value.Columns);
            case RunEvent.ColumnsResolved variant_value:
                return 4
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.SetIndex)
                    + FfiConverterSequenceTypeResultColumnInfo.INSTANCE.AllocationSize(variant_value.Columns);
            case RunEvent.RowsAppended variant_value:
                return 4
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.SetIndex)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.RowCount);
            case RunEvent.RowLimitReached variant_value:
                return 4
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.SetIndex)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.Retained);
            case RunEvent.ResultSetFinished variant_value:
                return 4
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.SetIndex)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.RowCount)
                    + FfiConverterOptionalUInt64.INSTANCE.AllocationSize(variant_value.TotalRows)
                    + FfiConverterTypeTruncationTag.INSTANCE.AllocationSize(variant_value.Truncation);
            case RunEvent.CommandCompleted variant_value:
                return 4
                    + FfiConverterOptionalUInt64.INSTANCE.AllocationSize(variant_value.RowsAffected);
            case RunEvent.Notice variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Severity)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Message)
                    + FfiConverterOptionalString.INSTANCE.AllocationSize(variant_value.Code);
            case RunEvent.Finished variant_value:
                return 4
                    + FfiConverterTypeRunOutcome.INSTANCE.AllocationSize(variant_value.Outcome)
                    + FfiConverterTypeTransactionStateTag.INSTANCE.AllocationSize(variant_value.Transaction);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRunEvent.AllocationSize()", value));
        }
    }

    public override void Write(RunEvent value, BigEndianStream stream) {
        switch (value) {
            case RunEvent.ResultSetStarted variant_value:
                stream.WriteInt(1);
                FfiConverterUInt32.INSTANCE.Write(variant_value.SetIndex, stream);
                FfiConverterSequenceTypeResultColumnInfo.INSTANCE.Write(variant_value.Columns, stream);
                break;
            case RunEvent.ColumnsResolved variant_value:
                stream.WriteInt(2);
                FfiConverterUInt32.INSTANCE.Write(variant_value.SetIndex, stream);
                FfiConverterSequenceTypeResultColumnInfo.INSTANCE.Write(variant_value.Columns, stream);
                break;
            case RunEvent.RowsAppended variant_value:
                stream.WriteInt(3);
                FfiConverterUInt32.INSTANCE.Write(variant_value.SetIndex, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.RowCount, stream);
                break;
            case RunEvent.RowLimitReached variant_value:
                stream.WriteInt(4);
                FfiConverterUInt32.INSTANCE.Write(variant_value.SetIndex, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.Retained, stream);
                break;
            case RunEvent.ResultSetFinished variant_value:
                stream.WriteInt(5);
                FfiConverterUInt32.INSTANCE.Write(variant_value.SetIndex, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.RowCount, stream);
                FfiConverterOptionalUInt64.INSTANCE.Write(variant_value.TotalRows, stream);
                FfiConverterTypeTruncationTag.INSTANCE.Write(variant_value.Truncation, stream);
                break;
            case RunEvent.CommandCompleted variant_value:
                stream.WriteInt(6);
                FfiConverterOptionalUInt64.INSTANCE.Write(variant_value.RowsAffected, stream);
                break;
            case RunEvent.Notice variant_value:
                stream.WriteInt(7);
                FfiConverterString.INSTANCE.Write(variant_value.Severity, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Message, stream);
                FfiConverterOptionalString.INSTANCE.Write(variant_value.Code, stream);
                break;
            case RunEvent.Finished variant_value:
                stream.WriteInt(8);
                FfiConverterTypeRunOutcome.INSTANCE.Write(variant_value.Outcome, stream);
                FfiConverterTypeTransactionStateTag.INSTANCE.Write(variant_value.Transaction, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRunEvent.Write()", value));
        }
    }
}







/// <summary>
/// How a run ended. A statement the server refused is `Failed`, not an
/// error of the call.
/// </summary>
internal record RunOutcome {
    
    public record Completed (
        ulong ElapsedMs
    ) : RunOutcome {}
    
    public record Failed (
        BoxedErrorInfo Info
    ) : RunOutcome {}
    
    public record Cancelled: RunOutcome {}
    
    
    public record TimedOut (
        bool ServerCancelled
    ) : RunOutcome {}
    

    
}

class FfiConverterTypeRunOutcome : FfiConverterRustBuffer<RunOutcome>{
    public static FfiConverterRustBuffer<RunOutcome> INSTANCE = new FfiConverterTypeRunOutcome();

    public override RunOutcome Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new RunOutcome.Completed(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 2:
                return new RunOutcome.Failed(
                    FfiConverterTypeBoxedErrorInfo.INSTANCE.Read(stream)
                );
            case 3:
                return new RunOutcome.Cancelled(
                );
            case 4:
                return new RunOutcome.TimedOut(
                    FfiConverterBoolean.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRunOutcome.Read()", value));
        }
    }

    public override int AllocationSize(RunOutcome value) {
        switch (value) {
            case RunOutcome.Completed variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.ElapsedMs);
            case RunOutcome.Failed variant_value:
                return 4
                    + FfiConverterTypeBoxedErrorInfo.INSTANCE.AllocationSize(variant_value.Info);
            case RunOutcome.Cancelled variant_value:
                return 4;
            case RunOutcome.TimedOut variant_value:
                return 4
                    + FfiConverterBoolean.INSTANCE.AllocationSize(variant_value.ServerCancelled);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRunOutcome.AllocationSize()", value));
        }
    }

    public override void Write(RunOutcome value, BigEndianStream stream) {
